draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // 504 as a broken circle (0) and a circle with a line through it, two distinct shapes
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 - 50, H/2);
  ctx.lineTo(W/2 + 100 + 50, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 50, 0, Math.PI * (1 + Math.sin(t)));
  ctx.stroke();
  ctx.restore();
}
